    if (event.region !== only) return to.skip();
    if (event.type === 'redline') return to.signal(redline, event.contractId, { text: event.text });
    return to.create({
      contractId: event.contractId,
      title: event.title,
      counterparty: event.counterparty,
      category: event.category,
